const _LS_GET_FN = 'getItem';
function _lsGet(key) {
  try {
    return localStorage?.[_LS_GET_FN]?.call(localStorage, key) ?? null;
  } catch (_e) {
    return null;
  }
}

function getCurrentUserId() {
  if (state?.user?.id) return String(state.user.id);
  return '';
}
function getProfileKey()    { const u = getCurrentUserId(); return u ? 'axisai_profile_' + u : ''; }
function getFmsLatestKey()  { const u = getCurrentUserId(); return u ? 'axisai_fms_latest_' + u : ''; }
function getTreinosKey()    { const u = getCurrentUserId(); return u ? 'axisai_treinos_' + u : ''; }
function getOnboardingKey() { const u = getCurrentUserId(); return u ? 'axisai_onboarding_done_' + u : ''; }
function getParqCacheKey()  { const u = getCurrentUserId(); return u ? 'axisai_parq_cache_' + u : ''; }
function getPhaseKey()      { const u = getCurrentUserId(); return u ? 'axisai_phase_' + u : ''; }
function getWorkoutsKey()   { const u = getCurrentUserId(); return u ? 'axisai_workouts_' + u : ''; } // v2
window.getWorkoutsKey = getWorkoutsKey;

function migrateLocalStorageKeys() {
  const userId = getCurrentUserId();
  if (!userId) return;
  ['axisai_profile','axisai_fms_latest','axisai_treinos','axisai_onboarding_done','axisai_phase','axisai_workouts'].forEach(function(key) {
    const val = _lsGet(key);
    const newKey = key + '_' + userId;
    if (val && !_lsGet(newKey)) {
      localStorage.setItem(newKey, val);
      localStorage.removeItem(key);
    } else if (val) {
      localStorage.removeItem(key);
    }
  });
}

function _showOnly(screenId) {
  ['screen-landing','screen-auth','screen-onboarding','screen-app'].forEach(id => {
    const el = document.getElementById(id) || (id === 'screen-landing' ? document.getElementById('landing-page') : null);
    if (!el) return;
    if (id === 'screen-app') {
      id === screenId ? el.classList.add('visible') : el.classList.remove('visible');
    } else {
      el.style.display = id === screenId ? '' : 'none';
    }
  });
}

async function _logError(fnName, error, context = {}) {
  const msg = error?.message || String(error);
  console.error(`[AXIS ERROR] ${fnName}:`, msg, context);
  try {
    const uid = (await supabase.auth.getUser())?.data?.user?.id;
    if (uid) {
      await supabase.from('error_logs').insert({
        user_id: uid,
        fn_name: fnName,
        error_message: msg,
        context
      });
    }
  } catch(e) { /* silencioso */ }
}

