function _clearLocalUserCache() {
  USER_LOCAL_KEYS.forEach((k) => localStorage.removeItem(k));
  // Limpa também chaves legadas sem user-scope (segurança + evitar contaminação cross-user)
  ['axisai_user', 'axisai_users'].forEach((k) => localStorage.removeItem(k));
  [getProfileKey(), getFmsLatestKey(), getTreinosKey(), getOnboardingKey(), getParqCacheKey(), getWorkoutsKey()].forEach(function(k) {
    if (k) localStorage.removeItem(k);
  });
}

function _resetRuntimeUserData() {
  state.profile = null;
  state.phase = null;
  state.readiness = null;
  state.chatHistory = [];
  state.fmsLatest = null;
  state.toeTouch = null;
  state.loadCtx = '';
  state.loadCtxUserId = null;
  _sessionLoadsBuffer = {};
  _activeSessionId = null;
  _activeWorkoutPlan = null;
  _sessionStartTime = null;
  _completedBlocks = new Set();
  if (_perfChartInstance) {
    try { _perfChartInstance.destroy(); } catch (_) {}
    _perfChartInstance = null;
  }
}

function _applyAuthenticatedUser(user, preferredName) {
  const prevId = state.user?.id || null;
  if (prevId && prevId !== user.id) {
    _clearLocalUserCache();
  }
  _resetRuntimeUserData();
  const fallbackName = user.email?.split('@')[0] || 'Atleta';
  const previousName = prevId === user.id ? state.user?.name : null;
  const resolvedName = preferredName || previousName || fallbackName;
  state.user = { name: resolvedName, email: user.email, id: user.id };
}

