function today() {
  return new Date().toISOString().split('T')[0];
}

async function loadUserData(userId) {
  // Reset in-memory state before loading to avoid cross-account leakage
  state.profile = null;
  state.checkin = null;
  state.phase = null;
  state.readiness = null;
  state.chatHistory = [];
  state.loadCtx = '';
  state.loadCtxUserId = null;

  const profileKey = getProfileKey();
  const phaseKey   = getPhaseKey();
  const cachedProfile = profileKey ? JSON.parse(_lsGet(profileKey) || 'null') : null;
  // Lê chave com user-scope; fallback para chave legacy sem scope (migrada por migrateLocalStorageKeys)
  const cachedPhase   = phaseKey ? JSON.parse(_lsGet(phaseKey) || 'null') : null;
  // axisai_checkin mantido apenas para compatibilidade com dados legacy no localStorage

  const [profile, phase, messages, readiness] = await Promise.all([
    supabase.from('profiles').select('*').eq('user_id', userId).maybeSingle(),
    supabase.from('training_phases').select('*').eq('user_id', userId).order('started_at', { ascending: false }).limit(1).maybeSingle(),
    supabase.from('chat_messages').select('*').eq('user_id', userId).order('created_at', { ascending: true }).limit(20),
    supabase.from('readiness_logs').select('*').eq('user_id', userId).eq('date', today()).maybeSingle()
  ]);

  if (profile.data) {
    state.profile = profile.data;
    if (profileKey) localStorage.setItem(profileKey, JSON.stringify(profile.data));
  } else if (cachedProfile && (cachedProfile.user_id === userId || String(cachedProfile.id || '') === String(userId))) {
    // Keep same-user cache as fallback when DB read is temporarily unavailable.
    state.profile = cachedProfile;
  }
  if (phase.data) {
    state.phase = phase.data;
    if (phaseKey) localStorage.setItem(phaseKey, JSON.stringify(phase.data));
    localStorage.removeItem('axisai_phase'); // remove legacy key sem scope
  } else if (cachedPhase && String(cachedPhase.user_id || '') === String(userId)) {
    state.phase = cachedPhase;
  }
  // state.checkin é alias de state.readiness (mesma fonte de dados)
  if (messages.data) {
    state.chatHistory = messages.data.map(m => ({ role: m.role, content: m.content }));
  }
  if (readiness.data) {
    state.readiness = readiness.data;
  }

  // Role check — set after profile is loaded
  const role = state.profile?.role || 'client';
  state.role = role;
  document.body.setAttribute('data-role', role);
  updateCoachNavIndicator();
  // ── Atualizar DOM de nome/avatar se app já estiver montado ──
  // loadUserData() pode ser chamado de múltiplos pontos (initApp, doLogin, etc.)
  // _refreshNameElements() é no-op se o DOM ainda não foi montado (guard interno).
  _refreshNameElements();
}

