function initParticles(canvasId, count) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const ctx = canvas.getContext('2d');

  function resize() {
    canvas.width = canvas.offsetWidth || canvas.parentElement?.offsetWidth || 800;
    canvas.height = canvas.offsetHeight || canvas.parentElement?.offsetHeight || 600;
  }
  resize();
  window.addEventListener('resize', resize);

  const neonHex = getComputedStyle(document.documentElement)
    .getPropertyValue('--neon').trim() || '#00FF88';
  function hexToRgb(hex) {
    const h = hex.replace('#','');
    const n = parseInt(h, 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }
  const { r, g, b } = hexToRgb(neonHex);

  const ORB_COUNT = 7;
  const ORBS = [];
  for (let i = 0; i < ORB_COUNT; i++) {
    ORBS.push({
      x:        0.1 + Math.random() * 0.8,
      y:        0.1 + Math.random() * 0.8,
      radius:   60 + Math.random() * 90,
      vx:       (Math.random() - 0.5) * 0.00022,
      vy:       (Math.random() - 0.5) * 0.00022,
      phase:    Math.random() * Math.PI * 2,
      phaseSpd: 0.002 + Math.random() * 0.003,
    });
  }

  function draw() {
    const W = canvas.width;
    const H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    ORBS.forEach(orb => {
      orb.x += orb.vx;
      orb.y += orb.vy;
      if (orb.x < 0.05 || orb.x > 0.95) orb.vx *= -1;
      if (orb.y < 0.05 || orb.y > 0.95) orb.vy *= -1;
      orb.phase += orb.phaseSpd;

      const alpha = 0.06 + 0.05 * Math.sin(orb.phase);
      const cx = orb.x * W;
      const cy = orb.y * H;

      // Glow externo difuso
      const glowR = orb.radius * 2.8;
      const glow = ctx.createRadialGradient(cx, cy, 0, cx, cy, glowR);
      glow.addColorStop(0,   `rgba(${r},${g},${b},${alpha})`);
      glow.addColorStop(0.5, `rgba(${r},${g},${b},${(alpha * 0.3).toFixed(3)})`);
      glow.addColorStop(1,   `rgba(${r},${g},${b},0)`);
      ctx.beginPath();
      ctx.arc(cx, cy, glowR, 0, Math.PI * 2);
      ctx.fillStyle = glow;
      ctx.fill();

      // Núcleo brilhante
      const coreR = orb.radius * 0.4;
      const core = ctx.createRadialGradient(cx, cy, 0, cx, cy, coreR);
      core.addColorStop(0,   `rgba(${r},${g},${b},${(alpha * 2).toFixed(3)})`);
      core.addColorStop(0.5, `rgba(${r},${g},${b},${(alpha * 0.8).toFixed(3)})`);
      core.addColorStop(1,   `rgba(${r},${g},${b},0)`);
      ctx.beginPath();
      ctx.arc(cx, cy, coreR, 0, Math.PI * 2);
      ctx.fillStyle = core;
      ctx.fill();
    });

    requestAnimationFrame(draw);
  }
  draw();
}

function initHeroReveal() {
  const lp = document.getElementById('landing-page');
  if (!lp) return;

  const updateReveal = () => {
    if (window.scrollY > 40) {
      lp.classList.add('lp-text-revealed');
      return;
    }
    lp.classList.remove('lp-text-revealed');
  };

  if (!_lpHeroRevealBound) {
    window.addEventListener('scroll', updateReveal, { passive: true });
    _lpHeroRevealBound = true;
  }

  updateReveal();
}

function initScrollFade() {
  const targets = document.querySelectorAll(
    '#lp-what, #lp-how, #lp-evolution, #lp-why, #lp-faq, #lp-cta-final, .lp-card'
  );
  targets.forEach(el => el.classList.add('lp-hidden'));

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.remove('lp-hidden');
        entry.target.classList.add('lp-visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.12 });

  targets.forEach(el => observer.observe(el));
}

async function initApp() {
  renderFMSGrid();
  updateCoachNavIndicator();
  document.getElementById('loading-overlay').style.display = 'flex';
  try {
    const { data: { session }, error } = await supabase.auth.getSession();
    const btn = document.getElementById('lp-cta-continue');
    const nameEl = document.getElementById('lp-continue-name');
    if (btn && nameEl && session?.user) {
      const profileKey = typeof getProfileKey === 'function' ? getProfileKey() : '';
      // Tentar pegar display_name do profile em cache
      let displayName = '';
      if (profileKey) {
        try {
          const cached = JSON.parse(_lsGet(profileKey) || '{}');
          displayName = cached.display_name || cached.full_name?.split(' ')[0] || '';
        } catch(_) {}
      }
      if (!displayName) {
        displayName = state.user?.name
                      || session.user.email?.split('@')[0]
                      || '';
      }
      if (displayName) {
        nameEl.textContent = displayName.toUpperCase();
        btn.style.display = '';
      }
    }
    if (error) {
      console.error('Session error:', error);
      document.getElementById('loading-overlay').style.display = 'none';
      showLandingPage();
      _authResolving = false;
      return;
    }
    if (session?.user) {
      const u = session.user;
      const savedName = state.user?.id === u.id ? state.user?.name : null;
      _applyAuthenticatedUser(u, savedName);
      migrateLocalStorageKeys();
      await loadUserData(u.id);
      _refreshNameElements(); // ← atualiza DOM após dados carregarem
      syncPendingWorkouts();
      loadWorkouts();
      loadProfile();
      await enterApp();
    } else {
      // No valid session — show auth screen
      showLandingPage();
      updateCoachNavIndicator();
    }
    document.getElementById('loading-overlay').style.display = 'none';
    _authResolving = false;
  } catch (e) {
    console.error('initApp error:', e);
    document.getElementById('loading-overlay').style.display = 'none';
    showLandingPage();
    _authResolving = false;
  }
}

window.addEventListener('DOMContentLoaded', () => {
  document.getElementById('w-goal')?.addEventListener('change', function() {
    const isEsportivo = this.value === 'Performance Esportiva';
    const group = document.getElementById('w-modalidade-group');
    const optGroup = document.getElementById('w-modalidade-opt-group');
    if (group) group.style.display = isEsportivo ? '' : 'none';
    if (optGroup) optGroup.style.display = isEsportivo ? 'none' : '';
  });
  document.querySelectorAll('img[src="NEW_LOGO"]').forEach(img => { img.src = NEW_LOGO; });
  migrateLocalStorageKeys();
  initApp();
});

supabase.auth.onAuthStateChange(async (event, session) => {
  _resolveAuthReady(session?.user || null);
  // ── FIX BUG 1: Prevent double routing ──
  // If initApp() is still resolving or the app was already entered, skip.
  // initApp() and doLogin() handle routing themselves; this listener only
  // acts as a fallback for external auth events (e.g. token refresh, OAuth redirect).
  if (event === 'SIGNED_IN' && session?.user) {
    if (_appEntered || _authResolving) return;
    const u = session.user;
    const savedName = state.user?.id === u.id ? state.user?.name : null;
    _applyAuthenticatedUser(u, savedName);
    migrateLocalStorageKeys();
    await loadUserData(u.id);
    syncPendingWorkouts();
    loadWorkouts();
    loadProfile();
    await enterApp();
  } else if (event === 'SIGNED_OUT') {
    _appEntered = false;
    _clearLocalUserCache();
    _resetRuntimeUserData();
    state.user = null;
    _showOnly('screen-auth');
  }
});

