function toggleFmsInfo(id) {
  const panel = document.getElementById('fms-info-' + id);
  if (!panel) return;
  const isOpen = panel.classList.contains('open');
  document.querySelectorAll('.fms-info-panel').forEach(p => p.classList.remove('open'));
  if (!isOpen) panel.classList.add('open');
}

document.addEventListener('click', function(e) {
  if (!e.target.classList.contains('fms-info-btn')) {
    document.querySelectorAll('.fms-info-panel').forEach(p => p.classList.remove('open'));
  }
});

// ═══════════════════════════════════════════════
//  SUPABASE SAVE HELPER (com fallback offline)
// ═══════════════════════════════════════════════
async function saveData(table, data, localKey) {
  localStorage.setItem(localKey, JSON.stringify(data)); // fallback imediato
  try {
    const { error } = await supabase.from(table).upsert(data);
    if (error) {
      console.warn(`[saveData] Supabase error on "${table}" [${error.code}]:`, error.message);
    }
  } catch (e) {
    console.warn('Supabase offline, dado salvo localmente:', e);
  }
}

// ═══════════════════════════════════════════════
//  AUTH
// ═══════════════════════════════════════════════
function switchTab(tab) {
  document.querySelectorAll('.auth-tab').forEach((el, i) => el.classList.toggle('active', tab === 'login' ? i === 0 : i === 1));
  document.getElementById('tab-login').style.display    = tab === 'login'    ? 'block' : 'none';
  document.getElementById('tab-register').style.display = tab === 'register' ? 'block' : 'none';
}

async function doLogin() {
  const email = document.getElementById('login-email').value.trim();
  const pass  = document.getElementById('login-pass').value;
  if (!email || !pass) return showToast('Preencha email e senha.', true);

  // ── Bloquear onAuthStateChange de agir durante o login manual ──
  // Sem isso, o SIGNED_IN disparado por signInWithPassword corre em paralelo
  // com doLogin(), causando race condition no loadUserData() e enterApp().
  _authResolving = true;

  try {
    // Limpar sessão local antes de logar com nova/mesma conta
    // Remove token Supabase explicitamente para garantir troca de conta limpa
    try {
      const _sbKey = Object.keys(localStorage).find(function(k) {
        return k.startsWith('sb-') && k.endsWith('-auth-token');
      });
      if (_sbKey) localStorage.removeItem(_sbKey);
    } catch (_) {}
    await supabase.auth.signOut({ scope: 'local' });

    const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
    if (error) { _authResolving = false; return showToast(error.message || 'Erro ao fazer login.', true); }
    if (!data?.user) { _authResolving = false; return showToast('Erro inesperado. Tente novamente.', true); }

    _applyAuthenticatedUser(data.user, data.user.email.split('@')[0]);

    // Carregar dados ANTES de entrar no app (evita estado parcial no dashboard)
    await loadUserData(data.user.id);
    _refreshNameElements(); // ← atualiza DOM após dados carregarem

    loadWorkouts();
    loadProfile();
    await enterApp();
  } finally {
    // Liberar o guard sempre — mesmo em caso de erro inesperado
    _authResolving = false;
  }
}

async function doRegister() {
  const name = document.getElementById('reg-name').value.trim();
  const email = document.getElementById('reg-email').value.trim();
  const pass = document.getElementById('reg-pass').value;
  if (!name || !email || !pass) return showToast('Preencha todos os campos.', true);
  if (pass.length < 6) return showToast('Senha deve ter ao menos 6 caracteres.', true);
  const { data, error } = await supabase.auth.signUp({ email, password: pass });
  if (error) return showToast(error.message || 'Erro ao criar conta.', true);
  if (!data?.user) return showToast('Verifique seu e-mail para confirmar o cadastro.', false);
  _clearLocalUserCache();
  state.user = { name, email, id: data.user.id };
  // Salvar nome no perfil
  if (data.user?.id) {
    await supabase.from('profiles').upsert({ user_id: data.user.id, display_name: name });
  }
  // onAuthStateChange (SIGNED_IN) will handle entering the app once session is confirmed
  showToast('Conta criada! Verifique seu e-mail para continuar.');
}

async function showForgotPassword() {
  const emailInput = document.getElementById('login-email');
  const email = (emailInput?.value?.trim()) || prompt('Digite seu email para recuperação:');
  if (!email) return;
  try {
    const res = await fetch('/api/reset-password', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email }),
    });
    if (res.ok) {
      showToast('Email de recuperação enviado! Verifique sua caixa de entrada.');
    } else {
      showToast('Erro ao enviar email de recuperação.', true);
    }
  } catch (err) {
    showToast('Erro de conexão: ' + err.message, true);
  }
}

async function doLogout() {
  [getProfileKey(), getFmsLatestKey(), getTreinosKey(), getOnboardingKey(), getParqCacheKey(), getPhaseKey()].forEach(function(k) {
    if (k) localStorage.removeItem(k);
  });
  // ── Limpar chaves legadas sem user-scope (não capturadas pelo getProfileKey etc.) ──
  // axisai_user e axisai_users contêm dados do usuário sem escopo — nunca são limpos
  // automaticamente. axisai_users armazena senhas em plaintext (issue de segurança).
  ['axisai_user', 'axisai_users', 'axisai_profile', 'axisai_fms_latest',
   'axisai_treinos', 'axisai_onboarding_done', 'axisai_phase', 'axisai_avatar',
   'axisai_checkin', 'axisai_lgpd_consent', 'axisai_workouts'].forEach(function(k) {
    localStorage.removeItem(k);
  });
  // ── FIX: remover token Supabase do localStorage de forma explícita ──
  // signOut() pode falhar silenciosamente em caso de erro de rede, deixando
  // o JWT do usuário anterior no localStorage e causando reautenticação cruzada.
  // Removemos a chave diretamente para garantir limpeza independente de rede.
  try {
    const _sbKey = Object.keys(localStorage).find(function(k) {
      return k.startsWith('sb-') && k.endsWith('-auth-token');
    });
    if (_sbKey) localStorage.removeItem(_sbKey);
  } catch (_) {}
  await supabase.auth.signOut();
  _clearLocalUserCache();
  _resetRuntimeUserData();
  state.user = null;
  state.workouts = [];
  _appEntered = false; // ── FIX BUG 1: Reset guard so next login can route correctly ──
  // ── FIX BUG: limpar DOM do chat para evitar vazamento de mensagens entre usuários ──
  const _chatBox = document.getElementById('chat-messages');
  if (_chatBox) _chatBox.innerHTML = '';
  updateCoachNavIndicator();
  document.getElementById('screen-app').classList.remove('visible');
  document.getElementById('screen-app').style.display = '';
  _showOnly('screen-auth');
}

function _hasRequiredProfileValue(value) {
  if (value === null || value === undefined) return false;
  if (typeof value === 'string') return value.trim().length > 0;
  return true;
}

function profileHasData(profile) {
  if (!profile) return false;
  // Fonte de verdade primária: campo onboarding_done do Supabase
  if (profile.onboarding_done === true) return true;
  // Fallback: qualquer campo de perfil preenchido indica usuário existente
  return profile.age != null || profile.objective != null || profile.weight != null ||
         profile.height != null || profile.level != null || profile.sex != null;
}

function _syncProfileCache(profile) {
  if (!profile || typeof profile !== 'object') return;
  const profileKey = getProfileKey();
  const onboardingKey = getOnboardingKey();
  if (profileKey) localStorage.setItem(profileKey, JSON.stringify(profile));
  if (profileHasData(profile)) {
    if (onboardingKey) localStorage.setItem(onboardingKey, '1');
  } else {
    if (onboardingKey) localStorage.removeItem(onboardingKey);
  }
}

function _isSkippableProfileQueryError(error, column) {
  const msg = String(error?.message || '').toLowerCase();
  if (error?.code === '42703' && msg.includes(`profiles.${column}`)) return true;
  if (error?.code === '22P02' && msg.includes('invalid input syntax for type integer')) return true;
  return false;
}

async function _getProfileFromSupabase(userId) {
  if (!userId) return null;
  const attempts = [
    { column: 'user_id', value: userId },
    { column: 'email', value: state.user?.email || null },
  ];

  for (const attempt of attempts) {
    if (!attempt.value) continue;
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq(attempt.column, attempt.value)
      .maybeSingle();

    if (error) {
      if (_isSkippableProfileQueryError(error, attempt.column)) continue;
      console.warn(`[onboarding status] profile fetch error (${attempt.column}):`, error);
      continue;
    }

    if (!data) continue;
    state.profile = { ...(state.profile || {}), ...data };
    _syncProfileCache(state.profile);
    return state.profile;
  }

  return null;
}

async function enterApp() {
  // ── Guard contra execução dupla — setado IMEDIATAMENTE para evitar race condition ──
  // Se duas chamadas concorrentes passarem pelo check antes de qualquer await, ambas
  // entrariam em completeEnterApp() e o DOM seria sobrescrito com dados parciais.
  if (_appEntered) return;
  _appEntered = true; // ← setado antes de qualquer await

  if (window._showingLanding) {
    window._showingLanding = false;
    _appEntered = false; // ← resetar se saindo sem entrar no app
    return;
  }
  migrateLocalStorageKeys();

  // ── Admin route — verificar ANTES do onboarding check ──
  if (window.location.pathname === '/admin') {
    const { data: { user } } = await supabase.auth.getUser();
    if (user?.id === '385d1288-b060-45c1-bfaf-4e90ba615c3e') {
      _appEntered = true;
      _showOnly('screen-app');
      showAdminPage();
      return;
    } else {
      window.history.replaceState({}, '', '/');
    }
  }

  // Source of truth: sempre consultar o perfil no Supabase após login.
  const profile = await _getProfileFromSupabase(state.user?.id);

  // Fallback defensivo no Supabase com campos mínimos para decisão de onboarding.
  // Evita falso-negativo quando o objeto de perfil chega parcial por timing/RLS.
  let fallbackProfile = null;
  if (!profile && state.user?.id) {
    const { data, error } = await supabase
      .from('profiles')
      .select('user_id, age, objective, weight, height, level, sex, onboarding_done, created_at')
      .eq('user_id', state.user.id)
      .maybeSingle();
    if (!error && data) {
      fallbackProfile = data;
      state.profile = { ...(state.profile || {}), ...data };
      _syncProfileCache(state.profile);
    }
  }

  // ── Fallback defensivo: quando o DB falha, usa cache local ──
  const profileKey = getProfileKey();
  const onboardingKey = getOnboardingKey();
  const cachedProfile  = profileKey ? JSON.parse(_lsGet(profileKey) || '{}') : {};
  const onboardingFlag = onboardingKey ? _lsGet(onboardingKey) === '1' : false;
  const resolvedProfile = profile || fallbackProfile || state.profile || cachedProfile;
  const hasCompletedOnboarding = onboardingFlag || profileHasData(resolvedProfile);

  if (!hasCompletedOnboarding) {
    _appEntered = false; // ← onboarding vai completar o fluxo via _finishWizard()
    showOnboarding();
    return;
  }

  if (!profile && profileHasData(cachedProfile)) {
    state.profile = { ...(state.profile || {}), ...cachedProfile };
  }

  // _appEntered já foi setado true no início da função
  await completeEnterApp();
}

function getDisplayName() {
  const profileKey = getProfileKey();
  const profile = state.profile || (profileKey ? JSON.parse(_lsGet(profileKey) || '{}') : {});
  const user = state.user || {};
  return profile.display_name ||
         profile.full_name?.split(' ')[0] ||
         user.name?.split('.')[0]?.toUpperCase() ||
         'ATLETA';
}

// ── Atualiza todos os elementos DOM com nome/avatar do usuário atual ──
// Chamada por completeEnterApp() e por loadUserData() após dados carregarem,
// garantindo que o DOM sempre reflete o usuário correto mesmo em casos de race.
function _refreshNameElements() {
  if (!document.getElementById('user-display-name')) return; // app ainda não montado
  const displayName = getDisplayName();
  const name = state.user?.name || '';
  const initial = name ? name.charAt(0).toUpperCase() : (displayName ? displayName.charAt(0) : 'A');
  const avatarEl = document.getElementById('user-avatar-letter');
  const nameEl = document.getElementById('user-display-name');
  const greetingEl = document.getElementById('greeting-name');
  const avatarBigEl = document.getElementById('profile-avatar-big');
  const profileNameEl = document.getElementById('profile-full-name');
  const emailEl = document.getElementById('profile-email-display');
  if (avatarEl) avatarEl.textContent = initial;
  if (nameEl) nameEl.textContent = displayName;
  if (greetingEl) greetingEl.textContent = displayName;
  if (avatarBigEl) avatarBigEl.textContent = initial;
  if (profileNameEl) profileNameEl.textContent = name || displayName;
  if (emailEl) emailEl.textContent = state.user?.email || '';
}
window._refreshNameElements = _refreshNameElements;

async function completeEnterApp() {
  document.getElementById('screen-onboarding').style.display = 'none';
  // ── FIX BUG 1: Ensure guard is set even when called directly from _finishWizard ──
  _appEntered = true;
  _showOnly('screen-app');
  const loadingOverlay = document.getElementById('loading-overlay');
  _refreshNameElements();
  loadAvatar();
  // ── FIX: sempre navegar para dashboard no carregamento do app
  // navigate('dashboard') já chama refreshDashboard() internamente e garante
  // que page-dashboard receba a classe 'active', evitando que o BFCache da PWA
  // restaure a última página ativa (ex: perfil) após CMD+R ou reload.
  await navigate('dashboard');
  if (loadingOverlay) loadingOverlay.style.display = 'none';
  refreshChatSidebar();
  await checkLGPDConsent();
  loadPrivacyToggles();
  // Auto-spawn check-in: só aparece se autenticado + sem check-in hoje
  setTimeout(checkAndShowReadinessModal, 600);
}

// Exibe o modal de check-in automaticamente se o usuário ainda não fez hoje.
// NUNCA chama openCheckinFlow() fora deste guard de autenticação.
async function checkAndShowReadinessModal() {
  if (!state.user?.id) return;                         // sessão não confirmada
  if (state.readiness) return;                         // já fez check-in hoje (carregado por loadUserData)
  if (document.getElementById('checkin-modal')) return; // modal já aberto (previne duplo-spawn)

  // Confirmação no banco — evita abrir modal se o dado ainda não chegou via loadUserData
  const { data, error } = await supabase
    .from('readiness_logs')
    .select('id')
    .eq('user_id', state.user.id)
    .eq('date', today())
    .maybeSingle();

  if (error) {
    // Tabela inexistente ou RLS bloqueando — não interromper o usuário
    console.warn('[readiness] checkAndShowReadinessModal:', error.code, error.message);
    return;
  }

  if (!data) {
    openCheckinFlow(); // abre SOMENTE se: autenticado + tabela OK + sem registro hoje
  }
}
